function SettledOpenTotal({ sheetId }: { sheetId: string }) {
  const { people, claims, rates, today, floor, late } = useSheetData(sheetId);
  const split = people.map((p) => settledAndOpen(p, people, claims, rates, today, floor, late));
  return (
    <p data-testid="rollup-settled-open">
      Settled <strong data-testid="rollup-settled-total">{sumDue(split.map(([s]) => s))}</strong>
      {' '}· Open <strong data-testid="rollup-open-total">{sumDue(split.map(([, o]) => o))}</strong>
    </p>
  );
}

/** The sheet's due-total: every person's due-total added up, skipping n/a, trimmed of the highest and lowest. */
export function useSheetDueTotal(sheetId: string) {
  const { people, claims, rates, today, floor, late, cap } = useSheetData(sheetId);
  return trimmedSum(people.map((p) => personDue(p, people, claims, rates, today, floor, late, cap)));
}

function DueTotal({ sheetId }: { sheetId: string }) {
  return (
    <p data-testid="rollup-due">
      Due total <strong data-testid="rollup-due-total">{useSheetDueTotal(sheetId)}</strong>
    </p>
  );
}

export const contributions = [
  ClaimCells.fill({ order: 10, Component: ClaimDue }),
  PersonHeaders.fill({ order: 15, Component: () => <th>Due</th> }),
  PersonCells.fill({ order: 15, Component: PersonDueTotal }),
  PersonHeaders.fill({ order: 15.2, Component: () => <><th>Settled</th><th>Open</th></> }),
  PersonCells.fill({ order: 15.2, Component: PersonSettledOpen }),
  PersonHeaders.fill({ order: 15.5, Component: () => <><th>0–30</th><th>31–60</th><th>61+</th></> }),
  PersonCells.fill({ order: 15.5, Component: PersonAged }),
  PersonHeaders.fill({ order: 16, Component: () => <th>Excess</th> }),
  PersonCells.fill({ order: 16, Component: PersonExcess }),
  PersonHeaders.fill({ order: 22, Component: () => <th>Backing</th> }),
  PersonCells.fill({ order: 22, Component: PersonBacking }),
  SheetPanel.fill({ order: 25, Component: DueTotal }),
  SheetPanel.fill({ order: 25.5, Component: SettledOpenTotal }),
];
import { useQuery } from '@tanstack/react-query';
import { ClaimCells } from '../../slots/defs/claimColumns';
import { PersonCells, PersonHeaders } from '../../slots/defs/personColumns';
import { SheetPanel } from '../../slots/defs/sheetPanel';
import { claimsQuery, counts } from '../claims/claimsQuery';
import type { Claim } from '../claims/claimsQuery';
import { peopleQuery } from '../people/peopleQuery';
import type { Person } from '../people/peopleQuery';
import { useSheetToday } from '../sheet/useSheetToday';
import { useFloor, useLate } from '../settings/settingsQuery';
import { figure, isOverdue, ratesQuery, sumDue, trimmedSum } from './ratesQuery';

function useOverdueData(sheetId: string) {
  return {
    people: useQuery(peopleQuery(sheetId)).data ?? [],
    claims: useQuery(claimsQuery(sheetId)).data ?? [],
    rates: useQuery(ratesQuery(sheetId)).data ?? [],
    today: useSheetToday(sheetId),
    floor: useFloor(sheetId),
    late: useLate(sheetId),
  };
}

type OverdueData = ReturnType<typeof useOverdueData>;

/** The overdue claims that count (a held person's OPEN claims do not), of one person or of the sheet, with their figures, late charges included. */
function overdue({ people, claims, rates, today, floor, late }: OverdueData, person?: Person) {
  const overdueClaims = claims.filter(
    (c) => (!person || c.personId === person.id) && counts(c, people, today) && isOverdue(c, late),
  );
  const figures = overdueClaims.map((c) => figure(c, rates, people.find((p) => p.id === c.personId), floor, late));
  return { count: overdueClaims.length, total: sumDue(figures) };
}

function ClaimDueBy({ sheetId, claim }: { sheetId: string; claim: Claim }) {
  const late = useLate(sheetId);
  return (
    <>
      <td data-testid="claim-due-by">{claim.dueBy}</td>
      <td data-testid="claim-overdue">{isOverdue(claim, late) ? 'yes' : 'no'}</td>
    </>
  );
}

function PersonOverdue({ sheetId, personId }: { sheetId: string; personId: number }) {
  const data = useOverdueData(sheetId);
  const person = data.people.find((p) => p.id === personId);
  const { count, total } = person ? overdue(data, person) : { count: 0, total: '0.00' };
  return (
    <td>
      <span data-testid="person-overdue-count">{count}</span> /{' '}
      <span data-testid="person-overdue-total">{total}</span>
    </td>
  );
}

/** The sheet's overdue claims that count: how many, and their total (every person's, trimmed of the highest and lowest). */
export function useSheetOverdue(sheetId: string) {
  const data = useOverdueData(sheetId);
  const { count } = overdue(data);
  return { count, total: trimmedSum(data.people.map((p) => overdue(data, p).total)) };
}

function OverdueTotal({ sheetId }: { sheetId: string }) {
  const { count, total } = useSheetOverdue(sheetId);
  return (
    <p data-testid="rollup-overdue">
      Overdue <strong data-testid="rollup-overdue-count">{count}</strong> totalling{' '}
      <strong data-testid="rollup-overdue-total">{total}</strong>
    </p>
  );
}

export const contributions = [
  ClaimCells.fill({ order: 12, Component: ClaimDueBy }),
  PersonHeaders.fill({ order: 16, Component: () => <th>Overdue</th> }),
  PersonCells.fill({ order: 16, Component: PersonOverdue }),
  SheetPanel.fill({ order: 26, Component: OverdueTotal }),
];
import { asString, useSearchParam } from '../../url/useSearchParam';

/** The signed-in name. There is no password: signing in is typing a name, kept in the URL. */
export function useUser() {
  return useSearchParam('user', asString);
}
import { getJson } from '../../api/http';
import { sheetKey } from '../sheet/sheetQuery';

export type Grade = 'A' | 'B' | 'C';
export const GRADES: Grade[] = ['A', 'B', 'C'];

/**
 * `version` is raised on every edit; an edit names the version it loaded. `retiredFrom` (yyyy-mm-dd) is
 * set once the person is retired, which they are at once, whatever the date; null otherwise. `held` is whether
 * they have any hold; `holds` are their holds by from-date: their OPEN claims dated within one, unless bound by a
 * statement, count in no live total. `terms` are their own terms in days, which come before those of their grade
 * and of the sheet; null for none. `contact` is their contact, trimmed and lower-cased, unique on the sheet; null
 * for none. `aliases` are their aliases, sorted as names are compared (ignoring case); the quick-add bar and the
 * paste box find a person by one as well as by the name. A name or alias is unique across the sheet's tree (its
 * ancestors and descendants); `clashing` is whether the person's name or an alias is used by someone else there all
 * the same (they were on the sheet before), which refuses every edit of them until a rename frees them. `origin` is
 * the id of the sheet they were transferred from; null when they were not transferred in. `retirements` are their
 * past retirements by from-date, each ended by unretiring them: a claim dated strictly between its dates is refused.
 */
export type Person = { id: number; name: string; grade: Grade; grades: Graded[]; version: number; retiredFrom: string | null; held: boolean; holds: Held[]; terms: number | null; contact: string | null; aliases: string[]; clashing: boolean; origin: string | null; retirements: Retired[] };

/** A past retirement from `from` to `to`, the day they were unretired (yyyy-mm-dd). */
export type Retired = { from: string; to: string };

/** A hold from `from` to `to` inclusive (yyyy-mm-dd); `to` is null when it has no end. */
export type Held = { from: string; to: string | null };

/** Whether the date (yyyy-mm-dd) falls within any of the person's holds. */
export function heldOn(person: Person | undefined, date: string): boolean {
  return (person?.holds ?? []).some((h) => h.from <= date && (h.to === null || date <= h.to));
}

/** A grade a person was given from `from` (yyyy-mm-dd) on; null for the first, from the beginning of time. */
export type Graded = { from: string | null; grade: Grade };

/** The person's grade in force on the date (yyyy-mm-dd): the one with the latest from-date on or before it. */
export function gradeOn(person: Person | undefined, date: string): Grade | undefined {
  if (!person) return undefined;
  // No from-date sorts as '', before every date.
  const applying = person.grades.filter((g) => (g.from ?? '') <= date);
  return applying.reduce<Graded | undefined>((best, g) => (!best || (g.from ?? '') > (best.from ?? '') ? g : best), undefined)
    ?.grade ?? person.grade;
}

/** Under the sheet's key, so re-loading the sheet re-reads its people. */
export const peopleKey = (sheetId: string) => [...sheetKey(sheetId), 'people'] as const;

export const peopleQuery = (sheetId: string) => ({
  queryKey: peopleKey(sheetId),
  queryFn: () => getJson<Person[]>(`/api/sheets/${encodeURIComponent(sheetId)}/people`),
});
